import { createRequire } from 'node:module'
import { homedir } from 'node:os'
import { join } from 'node:path'
import { existsSync, readdirSync } from 'node:fs'
import { writeFile } from 'node:fs/promises'
import assert from 'node:assert/strict'
const { chromium } = createRequire(import.meta.url)(join(homedir(), '.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright'))
const root = join(process.cwd(), 'docs/verification')
const base = join(process.env.LOCALAPPDATA, 'ms-playwright')
const executablePath = existsSync(chromium.executablePath()) ? undefined : readdirSync(base).filter(name => /^chromium-\d+$/.test(name)).sort((a,b) => Number(b.split('-')[1])-Number(a.split('-')[1])).map(name => join(base,name,'chrome-win64/chrome.exe')).find(existsSync)
const browser = await chromium.launch({ headless: true, executablePath })
const context = await browser.newContext({ viewport: { width: 1280, height: 860 } })
await context.addInitScript(() => localStorage.setItem('hover-island.preview.settings', JSON.stringify({onboardingVersion: 0, weatherCity: null, weatherLat: null, weatherLon: null, weatherAutoLocation: false})))
const page = await context.newPage()
page.setDefaultTimeout(30000)
const errors = [], results = [], screenshots = []
page.on('requestfailed', request => console.log('Request failed', request.url(), request.failure()?.errorText))
const pendingRequests = new Set()
page.on('request', request => pendingRequests.add(request.url()))
page.on('requestfinished', request => pendingRequests.delete(request.url()))
page.on('pageerror', error => errors.push(error.message))
 const shot = async name => { const path = join(root, `${name}-20261017.png`); await page.screenshot({ path }); screenshots.push(path); console.log('Captured', name) }
const patch = patch => page.evaluate(async patch => { const state = await import('/src/state/settings.ts'); state.patchSettings(patch); await state.flushSettings() }, patch)
try {
 await page.goto('http://127.0.0.1:1420/', {waitUntil:'domcontentloaded',timeout:90000})
 await page.getByRole('dialog').waitFor()
 await page.mouse.move(1200,800)
 await page.waitForTimeout(1000)
 assert.equal(await page.locator('.island--open').count(), 1)
 await shot('new-install-tour')
 results.push('New install tour remains visible when the pointer leaves')
 await page.getByRole('button',{name:'Skip introduction',exact:true}).click()
 await page.getByRole('dialog').waitFor({state:'hidden'})
 await page.getByText('Choose your weather location', {exact:true}).waitFor()
 await shot('weather-consent-empty')
 results.push('New user weather waits for manual city or explicit permission')
 await page.getByRole('button',{name:'Set up',exact:true}).click()
 await page.getByRole('button',{name:'Use device location',exact:true}).waitFor()
 assert.equal(await page.locator('.weather__temp').count(),0)
 await shot('weather-location-consent')
 await page.getByRole('textbox',{name:'Search for a weather location',exact:true}).fill('Dadri')
 await page.locator('.weather__search').getByRole('button',{name:'Search',exact:true}).click()
 await page.locator('.weather__locations button').first().click()
 await page.locator('.weather__temp').waitFor()
 await page.evaluate(async () => (await import('/src/state/ui.ts')).setPinned(true))
 for (const [name,width] of [['small',640],['medium',800],['large',960]]) {
  await patch({sizePreset:name,collapsed:{w:{small:256,medium:320,large:384}[name],h:38},expanded:{w:width,h:560}})
  await page.waitForTimeout(700)
  const geom = await page.locator('.island').evaluate(node => ({width:parseFloat(node.style.getPropertyValue('--island-spring-width')),height:parseFloat(node.style.getPropertyValue('--island-spring-height'))}))
  assert.ok(Math.abs(geom.width-width)<.2)
  assert.equal(geom.height,560)
  await shot(`weather-${name}`)
 }
 results.push('Size presets expand horizontally at a stable height; weather adapts without duplicate hero icons')
 assert.equal(await page.locator('.weather__now .weather-icon').count(),1)
 const savedWidgets=await page.evaluate(async()=>JSON.parse(JSON.stringify((await import('/src/state/settings.ts')).settings.widgets)))
 for (const size of ['compact','wide','full']) {
  await patch({sizePreset:'medium',expanded:{w:800,h:560},widgets:savedWidgets.map(widget=>({...widget,order:['weather','media','notes','focus'].indexOf(widget.kind),enabled:['weather','media','notes','focus'].includes(widget.kind),panel:'today',size:widget.kind==='weather'?size:'compact',slot:undefined}))})
  await page.evaluate(async()=>(await import('/src/state/panel.ts')).setActivePanel('today'))
  await page.locator(`.weather-card--${size}`).waitFor()
  await shot(`weather-tile-${size}`)
  const overflow=await page.locator('.weather-card').evaluate(node=>({client:node.clientHeight,scroll:node.scrollHeight}))
  assert.ok(overflow.scroll <= overflow.client+2, `${size} weather content fits`)
 }
 await patch({widgets:savedWidgets})
 results.push('Compact, wide and full weather tile branches fit their assigned space')
 await patch({background:'artwork'})
 await page.locator('.ambient__art').waitFor()
 await page.mouse.move(1200,800)
 await page.evaluate(async () => { const ui=await import('/src/state/ui.ts');ui.setPinned(false);ui.collapseIsland() })
 await page.waitForTimeout(900)
 assert.equal(await page.locator('.ambient__art').count(),0)
 assert.equal(await page.locator('.weather-card').count(),0)
 results.push('Collapsed shell releases artwork scene and weather DOM')
 await page.evaluate(() => {
  const stage=document.querySelector('.island-stage'); const dataTransfer=new DataTransfer();dataTransfer.items.add(new File(['x'],'example.txt'))
  stage.dispatchEvent(new DragEvent('dragover',{bubbles:true,clientX:640,clientY:400,dataTransfer}))
 })
 assert.equal(await page.locator('.file-drop-toast').count(),0)
 await page.evaluate(() => { const stage=document.querySelector('.island-stage'); const dataTransfer=new DataTransfer();dataTransfer.items.add(new File(['x'],'example.txt'));stage.dispatchEvent(new DragEvent('dragleave',{bubbles:true,dataTransfer})) })
 await page.waitForTimeout(750)
 assert.equal(await page.evaluate(async()=>(await import('/src/state/ui.ts')).surfaceInteractionActive()),false,'leaving a transparent drag area releases interaction ownership')
 results.push('File drag in transparent host area does not activate notch')
 await patch({placement:{edge:'left',mode:'notch',monitor:null},compactItems:['clock','weather','battery']})
 await page.waitForTimeout(700)
 const stack=await page.locator('.pill__compact-clock').evaluate(node=>getComputedStyle(node).flexDirection)
 assert.equal(stack,'column')
 assert.ok(await page.locator('.pill__clock-stack span').count() >= 2)
 await shot('side-notch-vertical')
 results.push('Side notch stacks time and status vertically')
 await patch({placement:{edge:'top',mode:'notch',monitor:null},background:'plain'})
 await page.evaluate(async () => {const ui=await import('/src/state/ui.ts');ui.expandIsland();ui.setPinned(true);(await import('/src/state/panel.ts')).showControls()})
 const slider=page.getByRole('slider',{name:'Display brightness',exact:true})
 await slider.waitFor()
 await page.evaluate(async()=>{const {cmd}=await import('/src/lib/ipc.ts');const read=cmd.quickControlsGet;cmd.quickControlsGet=async()=>({...await read(),brightness:{supported:true,level:70,error:null}})})
 await page.getByRole('button',{name:'Refresh quick settings',exact:true}).click()
 assert.equal(await slider.isDisabled(),false)
 const bounds=await slider.boundingBox()
 await page.mouse.move(bounds.x+bounds.width*.6,bounds.y+bounds.height*.5)
 await page.mouse.down()
 await page.evaluate(async () => (await import('/src/state/peek.ts')).ingestActionPeek({id:'smoke-brightness',app:'Brightness',title:'70%',body:'Sample slider acknowledgement',timestamp:Date.now()}))
 await page.waitForTimeout(1000)
 assert.equal(await page.locator('.live-activity').count(),0)
 assert.equal(await slider.isVisible(),true)
 await shot('brightness-hold')
 await page.mouse.up()
 await page.mouse.move(bounds.x+bounds.width*.6+1,bounds.y+bounds.height*.5)
 await page.locator('.live-activity').waitFor()
 await shot('brightness-after-release')
 results.push('Browser slider hold retains workspace; queued peek appears after release and quiet period')
 assert.deepEqual(errors,[])
} catch(error) {
 console.log('Pending requests', [...pendingRequests])
 await shot('interaction-smoke-failure')
 results.push({failure:String(error)})
 throw error
} finally {
 await writeFile(join(root,'interaction-weather-smoke-20261017.json'),JSON.stringify({results,errors,screenshots,scope:'Browser preview only; native location, shell drag, topmost and total WebView2 RAM not proven'},null,2))
 await browser.close()
 console.log(JSON.stringify({results,errors,screenshots},null,2))
}
